// This golden was generated by main at 9f3ffcee, before AST lowering. Keep its
// provenance: it provides an independent executable and syntax oracle, not a
// formatting snapshot to regenerate whenever the printer changes.
func TestGoASTLoweringAgainstBaseline(t *testing.T) {
	source, err := os.ReadFile("testdata/go-ast/program.ms")
	if err != nil {
		t.Fatal(err)
	}
	baseline, err := os.ReadFile("testdata/go-ast/baseline.go.txt")
	if err != nil {
		t.Fatal(err)
	}
	result := compiler.CompileSource("ast-lowering.ms", string(source), compiler.Options{Tests: true})
	if !result.Success() {
		t.Fatal(result.Diagnostics)
	}
	// Production optimizations may change executable AST shape. Retain this
	// independent behavior/source-map oracle; eligibility tests check new shapes.
	// Keep the independent checked-in oracle immutable. Native entry bodies may
	// omit fully supplied defaults, and boxed adapters may share a native body.
	if got := fmt.Sprintf("%x", sha256.Sum256(baseline)); got != "38d1c416f840003550800f362fdfb457d8f4ace168d48b98c9972a5cf0a6be61" {
		t.Fatal("independent baseline changed", got)
	}
	original, current := callableDirectives(t, string(baseline)), callableDirectives(t, result.Source)
	for name, variants := range original {
		want := variants[0]
		matched := false
		for _, got := range current[name] {
			matched = matched || reflect.DeepEqual(want, got)
			at := 0
			for _, directive := range got {
				for at < len(want) && want[at] != directive {
					at++
				}
				if at == len(want) {
					t.Fatalf("%s source directive changed order/target: %v outside %v", name, got, want)
				}
				at++
			}
		}
		if !matched {
			t.Fatalf("%s lost its complete source mapping: %v != %v", name, current[name], want)
		}
	}
	for name := range current {
		if original[name] == nil {
			t.Fatal("unexpected source callable", name)
		}
	}
	for i := 0; i < 3; i++ {
		repeated := compiler.CompileSource("ast-lowering.ms", string(source), compiler.Options{Tests: true})
		if !repeated.Success() || repeated.Source != result.Source {
			t.Fatal("nondeterministic Go output", repeated.Diagnostics)
		}
	}
	var outputs []string
	for _, source := range []string{string(baseline), result.Source} {
		binary := filepath.Join(t.TempDir(), "program")
		if err := Build(source, binary); err != nil {
			t.Fatal(err)
		}
		output, err := exec.Command(binary).CombinedOutput()
		if err != nil {
			t.Fatalf("generated executable: %v\n%s", err, output)
		}
		outputs = append(outputs, string(output))
	}
	if outputs[0] != outputs[1] || !strings.Contains(outputs[1], "1 tests, 0 failed") {
		t.Fatalf("baseline behavior differs: %q", outputs)
	}
}

// Inspect source-owned bodies separately: a typed entry and its boxed adapter
// can contain distinct copies, while caller-default locations occur only in the
// boxed copy. Each complete body and each specialized subsequence is checked.
func callableDirectives(t *testing.T, source string) map[string][][]string {
	t.Helper()
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "generated.go", source, parser.ParseComments)
	if err != nil {
		t.Fatal(err)
	}
	result := map[string][][]string{}
	ast.Inspect(file, func(n ast.Node) bool {
		var body *ast.BlockStmt
		switch n := n.(type) {
		case *ast.FuncDecl:
			body = n.Body
		case *ast.FuncLit:
			body = n.Body
		default:
			return true
		}
		if body == nil {
			return true
		}
		for _, stmt := range body.List {
			d, ok := stmt.(*ast.DeferStmt)
			if !ok {
				continue
			}
			sel, ok := d.Call.Fun.(*ast.SelectorExpr)
			if !ok || sel.Sel.Name != "TraceSource" {
				continue
			}
			name, err := strconv.Unquote(d.Call.Args[len(d.Call.Args)-1].(*ast.BasicLit).Value)
			if err != nil {
				t.Fatal(err)
			}
			start, end := fset.PositionFor(body.Pos(), false).Offset, fset.PositionFor(body.End(), false).Offset
			var directives []string
			for _, line := range sourceDirectives(source[start:end]) {
				// The source-position update and executable statement deliberately
				// share one source target; preserve all transitions and their order.
				if len(directives) == 0 || directives[len(directives)-1] != line {
					directives = append(directives, line)
				}
			}
			result[name] = append(result[name], directives)
			break
		}
		return true
	})
	return result
}

// Normalize only nonsemantic position information and redundant parentheses.
// Preserve operators, operand nesting/order, literal spelling, names and types.
func normalizedGo(t *testing.T, source string) []byte {
	t.Helper()
	file, err := parser.ParseFile(token.NewFileSet(), "generated.go", source, parser.SkipObjectResolution)
	if err != nil {
		t.Fatal(err)
	}
	data, err := json.Marshal(normalizeGoNode(reflect.ValueOf(file)))
	if err != nil {
		t.Fatal(err)
	}
	return data
}
func normalizeGoNode(value reflect.Value) any {
	if !value.IsValid() {
		return nil
	}
	switch value.Kind() {
	case reflect.Pointer, reflect.Interface:
		if value.IsNil() {
			return nil
		}
		if paren, ok := value.Interface().(*ast.ParenExpr); ok {
			return normalizeGoNode(reflect.ValueOf(paren.X))
		}
		return normalizeGoNode(value.Elem())
	case reflect.Struct:
		fields := map[string]any{"node": value.Type().Name()}
		for i := 0; i < value.NumField(); i++ {
			field := value.Type().Field(i)
			if field.Type == reflect.TypeOf(token.NoPos) {
				// These positions also encode syntax: variadic call expansion
				// and a type alias must not disappear from the semantic oracle.
				if field.Name == "Ellipsis" || field.Name == "Assign" {
					fields[field.Name] = value.Field(i).Interface().(token.Pos).IsValid()
				}
				continue
			}
			if field.Name == "Comments" || field.Name == "Comment" || field.Name == "Doc" {
				continue
			}
			fields[field.Name] = normalizeGoNode(value.Field(i))
		}
		return fields
	case reflect.Slice:
		var values []any
		for i := 0; i < value.Len(); i++ {
			values = append(values, normalizeGoNode(value.Index(i)))
		}
		return values
	default:
		return value.Interface()
	}
}

func TestGoASTComparisonRetainsSyntaxFlags(t *testing.T) {
	for _, pair := range [][2]string{
		{"package p; func f() { g(xs) }", "package p; func f() { g(xs...) }"},
		{"package p; type A B", "package p; type A = B"},
		{"package p; var v = a * (b + c)", "package p; var v = a * b + c"},
	} {
		if bytes.Equal(normalizedGo(t, pair[0]), normalizedGo(t, pair[1])) {
			t.Fatalf("semantic oracle equated different programs: %q", pair)
		}
	}
}

func sourceDirectives(source string) []string {
	var directives []string
	for _, line := range strings.Split(source, "\n") {
		if strings.HasPrefix(line, "//line ") {
			directives = append(directives, line)
		}
	}
	return directives
}

func TestGoASTPrecedenceAndEscaping(t *testing.T) {
	// These trees must keep their grouping even when the printer removes redundant
	// parentheses. Host keywords and runtime qualifier names are ordinary source
	// names and must retain the checker's distinct binding IDs.
	source := `fn value(chan: Bool, map: Bool, rt: Bool) -> Bool:
    return (chan or map) and rt
fn text() -> String:
    return "quote: \" slash: \\ tab: \t newline: \n λ"
`
	result := compiler.CompileSource("path with spaces: λ\nsource\r.ms", source, compiler.Options{})
	if !result.Success() {
		t.Fatal(result.Diagnostics)
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "generated.go", result.Source, parser.ParseComments|parser.SkipObjectResolution)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	ast.Inspect(file, func(node ast.Node) bool {
		if name, ok := node.(*ast.Ident); ok && !token.IsIdentifier(name.Name) {
			t.Errorf("invalid generated identifier %q", name.Name)
		}
		if expr, ok := node.(*ast.BinaryExpr); ok && expr.Op == token.LAND {
			// Bool conversions preserve the left OR as one argument, independent of
			// the relative precedence of Go's && and || operators.
			left := expr.X
			if conversion, ok := left.(*ast.CallExpr); ok && len(conversion.Args) == 1 {
				left = conversion.Args[0]
			}
			if paren, ok := left.(*ast.ParenExpr); ok {
				left = paren.X
			}
			inner, ok := left.(*ast.BinaryExpr)
			if !ok || inner.Op != token.LOR {
				t.Fatal("lost source grouping")
			}
			found = true
		}
		return true
	})
	if !found {
		t.Fatal("missing short-circuit tree")
	}
	if !strings.Contains(result.Source, "//line path with spaces: λ_source_.ms:2\n") {
		t.Fatal("source filename was not safely emitted")
	}
}
